import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<any>} [textContent]
 * @property {Array<{name:string,params:any,trigger?:string}>} [cinematicPrimitives]
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{loadTexture(url:string):Promise<any>}} textureLoader
 * @property {{emit(event:string,payload:any):void}} emit
 * @property {{[key:string]:(target:any,params:any)=>{timeline:any,cleanup:()=>void}}} primitives
 * @property {{createText(content:string,opts?:any):any}} fontAtlas
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const root = new Group();

  // ------- Plane with texture -------
  const planeGeometry = new PlaneGeometry(7, 6);
  const planeMaterial = new MeshBasicNodeMaterial();
  const planeMesh = new Mesh(planeGeometry, planeMaterial);
  root.add(planeMesh);

  // Load texture if URL is provided
  /** @type {any} */
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        planeMaterial.map = tex;
        planeMaterial.needsUpdate = true;
      })
      .catch(() => {
        // texture load failure – keep material untextured
      });
  }

  // ------- Text content -------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    // Expected fields: text, role, typography?.fontSize
    const fontSize = item.typography?.fontSize ?? 96;
    const color = '#16161d'; // ink from palette
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color,
      align: 'center',
    });
    // Position text slightly above the plane
    txt.position.set(0, 0.8, 0.01);
    root.add(txt);
  }

  // ------- Cinematic primitives -------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const prim = ctx.primitives[primitive.name];
      if (prim) {
        const { timeline, cleanup } = prim(root, primitive.params);
        // Store for later cleanup
        (root.userData._primitiveCleanups = root.userData._primitiveCleanups || []).push(cleanup);
        // If the primitive provides a timeline, keep reference to kill on cleanup
        (root.userData._gsapTimelines = root.userData._gsapTimelines || []).push(timeline);
      }
    }
  }

  // ------- Handlers placeholder -------
  root.userData.handlers = {};

  // ------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometry & material
    planeGeometry.dispose();
    planeMaterial.dispose();
    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }

    // Cleanup primitives
    if (root.userData._primitiveCleanups) {
      for (const fn of root.userData._primitiveCleanups) {
        try { fn(); } catch (_) {}
      }
    }

    // Kill GSAP timelines
    if (root.userData._gsapTimelines) {
      for (const tl of root.userData._gsapTimelines) {
        try { tl.kill(); } catch (_) {}
      }
    }

    // Remove references
    root.traverse((obj) => {
      obj.geometry && obj.geometry.dispose && obj.geometry.dispose();
      obj.material && obj.material.dispose && obj.material.dispose();
    });
  };

  return root;
}
